 /** Does an action pattern such as "doc:*" match an action such as "doc:read"? See README.md. */
 export function matchAction(pattern: string, action: string): boolean {
-  throw new Error("not implemented");
+  if (pattern === "*") {
+    return true;
+  }
+  if (pattern.endsWith(":*")) {
+    const prefix = pattern.slice(0, -1);
+    return action.startsWith(prefix) && action.length > prefix.length;
+  }
+  return pattern === action;
 }

 /** Does a resource pattern with * and ** segments match a path? See README.md. */
 export function matchResource(pattern: string, resource: string): boolean {
-  throw new Error("not implemented");
+  return matchSegments(splitPath(pattern), splitPath(resource));
 }
+
+function splitPath(path: string): string[] {
+  return path.split("/").filter((segment) => segment !== "");
+}
+
+function matchSegments(patternSegments: string[], resourceSegments: string[]): boolean {
+  if (patternSegments.length === 0) {
+    return resourceSegments.length === 0;
+  }
+  const [head, ...rest] = patternSegments;
+  if (head === "**") {
+    return matchSegments(rest, resourceSegments) || (resourceSegments.length > 0 && matchSegments(patternSegments, resourceSegments.slice(1)));
+  }
+  if (resourceSegments.length === 0) {
+    return false;
+  }
+  if (head === "*" || head === resourceSegments[0]) {
+    return matchSegments(rest, resourceSegments.slice(1));
+  }
+  return false;
+}
